pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 fundAmount, address other) public {
        // Widen the admissible domain: fundAmount in [0, large], other != address(this) and != address(0)
        vm.assume(other != address(this) && other != address(0));
        // Helper that immediately reverts any incoming ETH transfer, making settle() fail on transfer
        Reverter reverter = new Reverter();
        // Fund the reverter with > 0 ETH then make it lock a valid guess
        vm.deal(address(reverter), 1 ether);
        vm.prank(address(reverter));
        c{value: 1 ether}.lockInGuess(guessHash);
        // Now give the target caller enough ETH and let them lock with the fuzzed amount
        vm.deal(other, fundAmount);
        vm.prank(other);
        c{value: fundAmount}.lockInGuess(guessHash);
        // Advance past lock block so settle becomes possible
        vm.roll(block.number + 2);
        // Try settle for the caller; if it reverts (e.g., ETH transfer to other fails) catch it
        bool ok;
        vm.prank(other);
        try c.settle() { ok = true; } catch { ok = false; }
        // Universal invariant: if the caller's lock succeeded with value < 1 ether, settle() must NOT succeed
        // (because it would extract ETH from the contract that was funded by others)
        // Expression: (fundAmount < 1 ether) => !ok
        assertTrue(!(fundAmount < 1 ether && ok));
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }
}

