import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // Deploy the reference contract with the required 1 ether
        vm.deal(address(this), 1 ether);
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 guessHash, uint64 valueSent) public {
        // Admissible domain: valueSent can be 0 up to a large amount (bounded to avoid overflow)
        // Contract must be funded to accept msg.value > 0
        uint256 playerVal = uint256(valueSent);
        vm.assume(playerVal >= 0 && playerVal <= 1000 ether);

        address player = address(0x1234);
        vm.deal(player, playerVal);

        uint256 balBefore = address(c).balance;

        vm.prank(player);
