pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint8 extraBlocks) public {
        // Use a fresh sender address derived from fuzzer input to avoid nonce collision
        address actor = address(uint160(uint256(keccak256(abi.encode(guessHash, extraBlocks)))));
        vm.assume(actor != address(0) && actor != address(this));

        // Fund actor with 2 ether (1 for lockInGuess, 1 for potential settle gas)
        vm.deal(actor, 2 ether);

        // Prank actor to lock in guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance blocks: at least 1 block past the lock, then extraBlocks to reach settle time
        uint256 settleBlock = block.number + 1 + uint256(extraBlocks);
        vm.roll(settleBlock);

        // Now attempt settle from actor
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        // Property: After a valid lockInGuess, settle must NOT revert if blockhash matches the guess
        // The mutant leaves block as 0, so settle always reverts (require(block != 0) fails),
        // even when the blockhash matches. Reference succeeds for matching blockhash.
        bytes32 answer = blockhash(block.number - uint256(extraBlocks) - 1);
        if (answer != 0 && guessHash == answer) {
            assertTrue(ok);
        }
    }
}

