pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
        vm.deal(address(this), 10 ether);
    }
    function testFuzz_property(bytes32 guess1, bytes32 guess2, uint256 blockAdvance1, uint256 blockAdvance2) public {
        // Restrict block advances to admissible positive deltas to keep the domain wide
        vm.assume(blockAdvance1 > 0 && blockAdvance1 < 256);
        vm.assume(blockAdvance2 > 0 && blockAdvance2 < 256);
        vm.assume(guess1 != guess2);
        bytes32 answer = bytes32(uint256(0));
        // Ensure at least one guess matches its blockhash to trigger the difference
        // We pre-roll, lock, roll forward, and use vm.roll to control blockhash on Foundry

        // Actor 1
        address actor1 = address(1);
        vm.deal(actor1, 10 ether);
        vm.prank(actor1);
        c.lockInGuess{value: 1 ether}(guess1);
        vm.roll(block.number + blockAdvance1);
        // Retrieve the blockhash that actor1 will see
        answer = blockhash(block.number - 1);

        // Actor 2
        address actor2 = address(2);
        vm.deal(actor2, 10 ether);
        vm.roll(block.number + 1); // advance to a clean new block
        uint256 actor2Block = block.number;
        vm.prank(actor2);
        c.lockInGuess{value: 1 ether}(guess2);
        vm.roll(block.number + blockAdvance2);

        // Settle actor1 with its own answer (which may or may not match)
        uint256 bal1Before = actor1.balance;
        vm.prank(actor1);
        bool ok1 = false;
        try c.settle() { ok1 = true; } catch { ok1 = false; }
        uint256 bal1After = actor1.balance;

        // Settle actor2 with the SAME answer that actor1 used
        // Because we set actor2's guess to guess2, it will not match unless fuzzer finds guess2==answer.
        // But the property we check is not about matching, it is about the rule:
        // "if settle succeeds, the caller receives exactly 2 ether".
        vm.prank(actor2);
        bool ok2 = false;
        uint256 bal2Before = actor2.balance;
        try c.settle() { ok2 = true; } catch { ok2 = false; }
        uint256 bal2After = actor2.balance;

        // The general rule: for any caller, if settle does not revert, the balance increase is exactly 2 ether.
        // The mutant stores 0 for guess, so settle will never transfer 2 ether even when ok is true.
        // We assert that for both actors, ok => received 2 ether.
        if (ok1) {
            assertTrue(bal1After - bal1Before == 2 ether);
        }
        if (ok2) {
            assertTrue(bal2After - bal2Before == 2 ether);
        }
    }
}

